下面是一个单文件 HTML 版本,保存为 `ssq.html` 后用浏览器直接打开即可,不需要任何依赖。

```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>双色球生成器</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    font-family: -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
    background: linear-gradient(135deg, #1e2a4a, #3b2a5e);
    color: #fff;
    display: flex;
    justify-content: center;
    padding: 40px 16px;
  }
  .container {
    width: 100%;
    max-width: 560px;
    background: rgba(255, 255, 255, 0.08);
    border-radius: 16px;
    padding: 28px;
    backdrop-filter: blur(8px);
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  }
  h1 { margin: 0 0 6px; text-align: center; font-size: 26px; }
  .sub { text-align: center; color: #c9c9e0; font-size: 13px; margin-bottom: 24px; }
  .controls {
    display: flex;
    gap: 12px;
    align-items: center;
    justify-content: center;
    margin-bottom: 24px;
    flex-wrap: wrap;
  }
  select, button {
    font-size: 15px;
    padding: 10px 16px;
    border-radius: 8px;
    border: none;
    outline: none;
  }
  select { background: #fff; color: #333; }
  button { cursor: pointer; font-weight: 600; transition: transform 0.1s, opacity 0.2s; }
  button:active { transform: scale(0.96); }
  .btn-primary { background: #ff4d4f; color: #fff; }
  .btn-secondary { background: rgba(255, 255, 255, 0.2); color: #fff; }
  .btn-primary:hover, .btn-secondary:hover { opacity: 0.85; }
  .ticket {
    display: flex;
    align-items: center;
    gap: 8px;
    background: rgba(255, 255, 255, 0.1);
    padding: 12px 14px;
    border-radius: 12px;
    margin-bottom: 10px;
    animation: fadeIn 0.3s ease;
  }
  .index { width: 28px; color: #c9c9e0; font-size: 13px; }
  .ball {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 15px;
    box-shadow: inset -3px -3px 6px rgba(0, 0, 0, 0.25), 0 2px 4px rgba(0, 0, 0, 0.3);
  }
  .red { background: radial-gradient(circle at 30% 30%, #ff7875, #d9363e); }
  .blue { background: radial-gradient(circle at 30% 30%, #69b1ff, #1d5fd1); margin-left: 6px; }
  .empty { text-align: center; color: #aaa; padding: 24px 0; }
  .toast {
    text-align: center;
    height: 20px;
    font-size: 13px;
    color: #95de64;
    margin-top: 8px;
  }
  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(6px); }
    to { opacity: 1; transform: translateY(0); }
  }
  @media (max-width: 420px) {
    .ball { width: 30px; height: 30px; font-size: 13px; }
  }
</style>
</head>
<body>
  <div class="container">
    <h1>🎱 双色球生成器</h1>
    <div class="sub">红球 1-33 选 6 个 · 蓝球 1-16 选 1 个</div>

    <div class="controls">
      <label>注数:
        <select id="count">
          <option value="1">1</option>
          <option value="2">2</option>
          <option value="3">3</option>
          <option value="5" selected>5</option>
          <option value="10">10</option>
        </select>
      </label>
      <button class="btn-primary" id="generate">生成号码</button>
      <button class="btn-secondary" id="copy">复制结果</button>
    </div>

    <div id="result"><div class="empty">点击“生成号码”开始</div></div>
    <div class="toast" id="toast"></div>
  </div>

<script>
  const pad = n => String(n).padStart(2, "0");

  function generateTicket() {
    const pool = Array.from({ length: 33 }, (_, i) => i + 1);
    // Fisher-Yates 洗牌,取前 6 个
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    const reds = pool.slice(0, 6).sort((a, b) => a - b);
    const blue = Math.floor(Math.random() * 16) + 1;
    return { reds, blue };
  }

  let tickets = [];

  function render() {
    const box = document.getElementById("result");
    if (!tickets.length) {
      box.innerHTML = '<div class="empty">点击“生成号码”开始</div>';
      return;
    }
    box.innerHTML = tickets.map((t, i) => `
      <div class="ticket">
        <span class="index">${i + 1}.</span>
        ${t.reds.map(n => `<div class="ball red">${pad(n)}</div>`).join("")}
        <div class="ball blue">${pad(t.blue)}</div>
      </div>
    `).join("");
  }

  function showToast(msg) {
    const el = document.getElementById("toast");
    el.textContent = msg;
    setTimeout(() => (el.textContent = ""), 1800);
  }

  document.getElementById("generate").addEventListener("click", () => {
    const n = parseInt(document.getElementById("count").value, 10);
    tickets = Array.from({ length: n }, generateTicket);
    render();
  });

  document.getElementById("copy").addEventListener("click", async () => {
    if (!tickets.length) return showToast("请先生成号码");
    const text = tickets
      .map((t, i) => `第${i + 1}注  红球: ${t.reds.map(pad).join(" ")}  蓝球: ${pad(t.blue)}`)
      .join("\n");
    try {
      await navigator.clipboard.writeText(text);
      showToast("已复制到剪贴板");
    } catch {
      showToast("复制失败,请手动选择文本");
    }
  });
</script>
</body>
</html>
```

**使用方法**

1. 把代码保存为 `ssq.html`
2. 双击用浏览器打开(macOS 也可以在终端运行 `open ssq.html`)
3. 选择注数,点击"生成号码"

**功能**

- 红球 6 个不重复并升序排列,蓝球 1 个
- 可选 1 / 2 / 3 / 5 / 10 注
- 红蓝球用不同颜色的立体球样式展示
- 一键复制结果为文本
- 适配手机屏幕

随机选号不会提高中奖概率,仅供娱乐。需要的话我可以再加上历史记录、胆码锁定或排除号码等功能。

我把两个彩种合并到同一个页面,顶部用标签页切换。大乐透规则:前区从 1-35 中选 5 个不重复号码,后区从 1-12 中选 2 个不重复号码,均升序排列。

保存为 `lottery.html`,用浏览器打开即可:

```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>彩票号码生成器</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    font-family: -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
    background: linear-gradient(135deg, #1e2a4a, #3b2a5e);
    color: #fff;
    display: flex;
    justify-content: center;
    padding: 40px 16px;
  }
  .container {
    width: 100%;
    max-width: 600px;
    background: rgba(255, 255, 255, 0.08);
    border-radius: 16px;
    padding: 28px;
    backdrop-filter: blur(8px);
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  }
  h1 { margin: 0 0 20px; text-align: center; font-size: 26px; }
  .tabs {
    display: flex;
    background: rgba(0, 0, 0, 0.25);
    border-radius: 10px;
    padding: 4px;
    margin-bottom: 18px;
  }
  .tab {
    flex: 1;
    padding: 10px 0;
    text-align: center;
    border-radius: 8px;
    cursor: pointer;
    font-weight: 600;
    color: #c9c9e0;
    transition: background 0.2s, color 0.2s;
    user-select: none;
  }
  .tab.active { background: #fff; color: #3b2a5e; }
  .sub { text-align: center; color: #c9c9e0; font-size: 13px; margin-bottom: 22px; }
  .controls {
    display: flex;
    gap: 12px;
    align-items: center;
    justify-content: center;
    margin-bottom: 24px;
    flex-wrap: wrap;
  }
  select, button {
    font-size: 15px;
    padding: 10px 16px;
    border-radius: 8px;
    border: none;
    outline: none;
  }
  select { background: #fff; color: #333; }
  button { cursor: pointer; font-weight: 600; transition: transform 0.1s, opacity 0.2s; }
  button:active { transform: scale(0.96); }
  .btn-primary { background: #ff4d4f; color: #fff; }
  .btn-secondary { background: rgba(255, 255, 255, 0.2); color: #fff; }
  .btn-primary:hover, .btn-secondary:hover { opacity: 0.85; }
  .ticket {
    display: flex;
    align-items: center;
    gap: 8px;
    background: rgba(255, 255, 255, 0.1);
    padding: 12px 14px;
    border-radius: 12px;
    margin-bottom: 10px;
    animation: fadeIn 0.3s ease;
  }
  .index { width: 28px; color: #c9c9e0; font-size: 13px; flex-shrink: 0; }
  .ball {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 15px;
    box-shadow: inset -3px -3px 6px rgba(0, 0, 0, 0.25), 0 2px 4px rgba(0, 0, 0, 0.3);
  }
  .red { background: radial-gradient(circle at 30% 30%, #ff7875, #d9363e); }
  .blue { background: radial-gradient(circle at 30% 30%, #69b1ff, #1d5fd1); }
  .gap { width: 6px; }
  .empty { text-align: center; color: #aaa; padding: 24px 0; }
  .toast { text-align: center; height: 20px; font-size: 13px; color: #95de64; margin-top: 8px; }
  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(6px); }
    to { opacity: 1; transform: translateY(0); }
  }
  @media (max-width: 460px) {
    .ball { width: 28px; height: 28px; font-size: 12px; }
    .ticket { gap: 5px; padding: 10px; }
  }
</style>
</head>
<body>
  <div class="container">
    <h1>🎱 彩票号码生成器</h1>

    <div class="tabs">
      <div class="tab active" data-game="ssq">双色球</div>
      <div class="tab" data-game="dlt">大乐透</div>
    </div>

    <div class="sub" id="rule"></div>

    <div class="controls">
      <label>注数:
        <select id="count">
          <option value="1">1</option>
          <option value="2">2</option>
          <option value="3">3</option>
          <option value="5" selected>5</option>
          <option value="10">10</option>
        </select>
      </label>
      <button class="btn-primary" id="generate">生成号码</button>
      <button class="btn-secondary" id="copy">复制结果</button>
    </div>

    <div id="result"></div>
    <div class="toast" id="toast"></div>
  </div>

<script>
  const pad = n => String(n).padStart(2, "0");

  // 彩种配置:主区(red)与副区(blue)的取值范围和个数
  const GAMES = {
    ssq: {
      name: "双色球",
      rule: "红球 1-33 选 6 个 · 蓝球 1-16 选 1 个",
      redMax: 33, redCount: 6,
      blueMax: 16, blueCount: 1,
      redLabel: "红球", blueLabel: "蓝球",
    },
    dlt: {
      name: "大乐透",
      rule: "前区 1-35 选 5 个 · 后区 1-12 选 2 个",
      redMax: 35, redCount: 5,
      blueMax: 12, blueCount: 2,
      redLabel: "前区", blueLabel: "后区",
    },
  };

  // 从 1..max 中不重复地随机抽取 count 个,升序返回
  function pick(max, count) {
    const pool = Array.from({ length: max }, (_, i) => i + 1);
    for (let i = pool.length - 1; i > 0; i--) {  // Fisher-Yates 洗牌
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    return pool.slice(0, count).sort((a, b) => a - b);
  }

  function generateTicket(game) {
    const g = GAMES[game];
    return {
      reds: pick(g.redMax, g.redCount),
      blues: pick(g.blueMax, g.blueCount),
    };
  }

  let currentGame = "ssq";
  // 每个彩种各自保存结果,切换标签页时不会丢失
  const results = { ssq: [], dlt: [] };

  function render() {
    const box = document.getElementById("result");
    const tickets = results[currentGame];
    document.getElementById("rule").textContent = GAMES[currentGame].rule;

    if (!tickets.length) {
      box.innerHTML = '<div class="empty">点击“生成号码”开始</div>';
      return;
    }
    box.innerHTML = tickets.map((t, i) => `
      <div class="ticket">
        <span class="index">${i + 1}.</span>
        ${t.reds.map(n => `<div class="ball red">${pad(n)}</div>`).join("")}
        <div class="gap"></div>
        ${t.blues.map(n => `<div class="ball blue">${pad(n)}</div>`).join("")}
      </div>
    `).join("");
  }

  function showToast(msg) {
    const el = document.getElementById("toast");
    el.textContent = msg;
    setTimeout(() => (el.textContent = ""), 1800);
  }

  // 切换标签页
  document.querySelectorAll(".tab").forEach(tab => {
    tab.addEventListener("click", () => {
      document.querySelectorAll(".tab").forEach(t => t.classList.remove("active"));
      tab.classList.add("active");
      currentGame = tab.dataset.game;
      render();
    });
  });

  // 生成
  document.getElementById("generate").addEventListener("click", () => {
    const n = parseInt(document.getElementById("count").value, 10);
    results[currentGame] = Array.from({ length: n }, () => generateTicket(currentGame));
    render();
  });

  // 复制
  document.getElementById("copy").addEventListener("click", async () => {
    const tickets = results[currentGame];
    if (!tickets.length) return showToast("请先生成号码");
    const g = GAMES[currentGame];
    const text = `【${g.name}】\n` + tickets
      .map((t, i) =>
        `第${i + 1}注  ${g.redLabel}: ${t.reds.map(pad).join(" ")}  ${g.blueLabel}: ${t.blues.map(pad).join(" ")}`)
      .join("\n");
    try {
      await navigator.clipboard.writeText(text);
      showToast("已复制到剪贴板");
    } catch {
      showToast("复制失败,请手动选择文本");
    }
  });

  render();
</script>
</body>
</html>
```

**主要改动**

- 顶部新增"双色球 / 大乐透"标签页,切换时各自保留已生成的结果
- 用 `GAMES` 配置对象描述每个彩种的号码范围和个数,生成逻辑共用一个 `pick()` 函数,以后想加其他彩种(如七乐彩、快乐8)只需要补一项配置
- 大乐透的后区 2 个号码也是不重复并升序排列
- 复制的文本会带上彩种名称,例如:

```
【大乐透】
第1注  前区: 03 12 19 27 34  后区: 05 11
```

同样提醒一下,随机选号不会提高中奖概率,仅供娱乐。

