   *   excludePrev 从上一个区域已选的号码之外抽取(七乐彩特别号)
   */
  const GAMES = {
    ssq: {
      name: "双色球", group: "fc",
      rule: "红球 1-33 选 6 个 · 蓝球 1-16 选 1 个",
      zones: [
        { label: "红球", min: 1, max: 33, count: 6, unique: true, sort: true, color: "red" },
        { label: "蓝球", min: 1, max: 16, count: 1, unique: true, sort: true, color: "blue" },
      ],
    },
    d3: {
      name: "福彩3D", group: "fc",
      rule: "3 位数字,每位 0-9,可重复",
      zones: [
        { label: "号码", min: 0, max: 9, count: 3, unique: false, sort: false, color: "red", pad: false },
      ],
    },
    qlc: {
      name: "七乐彩", group: "fc",
      rule: "1-30 选 7 个基本号 + 1 个特别号(特别号不与基本号重复)",
      zones: [
        { label: "基本号", min: 1, max: 30, count: 7, unique: true, sort: true, color: "red" },
        { label: "特别号", min: 1, max: 30, count: 1, unique: true, sort: true, color: "blue", excludePrev: true },
      ],
    },
    kl8: {
      name: "快乐8", group: "fc",
      rule: "1-80 中选 1~10 个号码(选一至选十)",
      variableCount: { min: 1, max: 10, def: 10 },
      zones: [
        { label: "选号", min: 1, max: 80, count: 10, unique: true, sort: true, color: "red" },
      ],
    },
    dlt: {
      name: "大乐透", group: "tc",
      rule: "前区 1-35 选 5 个 · 后区 1-12 选 2 个",
      zones: [
        { label: "前区", min: 1, max: 35, count: 5, unique: true, sort: true, color: "red" },
        { label: "后区", min: 1, max: 12, count: 2, unique: true, sort: true, color: "blue" },
      ],
    },
    pl3: {
      name: "排列3", group: "tc",
      rule: "3 位数字,每位 0-9,可重复",
      zones: [
        { label: "号码", min: 0, max: 9, count: 3, unique: false, sort: false, color: "red", pad: false },
      ],
    },
    pl5: {
      name: "排列5", group: "tc",
      rule: "5 位数字,每位 0-9,可重复",
      zones: [
        { label: "号码", min: 0, max: 9, count: 5, unique: false, sort: false, color: "red", pad: false },
      ],
    },
    qxc: {
      name: "七星彩", group: "tc",
      rule: "前 6 位每位 0-9(可重复) + 最后 1 位 0-14",
      zones: [
        { label: "前区", min: 0, max: 9,  count: 6, unique: false, sort: false, color: "red",  pad: false },
        { label: "后区", min: 0, max: 14, count: 1, unique: false, sort: false, color: "blue", pad: false },
      ],
    },
  };

  const pad2 = n => String(n).padStart(2, "0");
  const fmt = (n, zone) => (zone.pad === false ? String(n) : pad2(n));
  const randInt = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;

  // 按号码区规则抽取号码
  function pickZone(zone, exclude = []) {
    let nums;
    if (zone.unique) {
      const pool = [];
      for (let i = zone.min; i <= zone.max; i++) {
        if (!exclude.includes(i)) pool.push(i);
      }
      for (let i = pool.length - 1; i > 0; i--) {  // Fisher-Yates 洗牌
        const j = randInt(0, i);
        [pool[i], pool[j]] = [pool[j], pool[i]];
      }
      nums = pool.slice(0, zone.count);
    } else {
      nums = Array.from({ length: zone.count }, () => randInt(zone.min, zone.max));
    }
    return zone.sort ? nums.sort((a, b) => a - b) : nums;
  }

  function generateTicket(gameKey, picks) {
    const game = GAMES[gameKey];
    const ticket = [];
    game.zones.forEach((zone, idx) => {
      const z = { ...zone };
      if (game.variableCount && idx === 0) z.count = picks;
      const exclude = zone.excludePrev ? ticket[idx - 1] : [];
      ticket.push(pickZone(z, exclude));
    });
    return ticket;  // 二维数组:每个号码区一组号码
  }

  let currentGame = "ssq";
  const results = {};
  Object.keys(GAMES).forEach(k => (results[k] = []));

  function currentPicks() {
    const game = GAMES[currentGame];
    return game.variableCount ? parseInt(document.getElementById("picks").value, 10) : null;
  }

  function render() {
    const game = GAMES[currentGame];
    const tickets = results[currentGame];
    document.getElementById("rule").textContent = game.rule;

    // 快乐8 才显示"选号个数"
    const wrap = document.getElementById("picks-wrap");
    wrap.classList.toggle("hidden", !game.variableCount);

    const box = document.getElementById("result");
    if (!tickets.length) {
      box.innerHTML = '<div class="empty">点击“生成号码”开始</div>';
      return;
    }
    box.innerHTML = tickets.map((t, i) => `
      <div class="ticket">
        <span class="index">${i + 1}.</span>
        ${t.map((nums, zi) => {
          const zone = game.zones[zi];
          const balls = nums.map(n => `<div class="ball ${zone.color}">${fmt(n, zone)}</div>`).join("");
          return (zi > 0 ? '<div class="gap"></div>' : "") + balls;
        }).join("")}
      </div>
    `).join("");
  }

  function showToast(msg) {
    const el = document.getElementById("toast");
    el.textContent = msg;
    setTimeout(() => (el.textContent = ""), 1800);
  }

  // 构建标签页
  function buildTabs() {
    Object.entries(GAMES).forEach(([key, game]) => {
      const el = document.createElement("div");
      el.className = "tab" + (key === currentGame ? " active" : "");
      el.textContent = game.name;
      el.dataset.game = key;
      el.addEventListener("click", () => {
        document.querySelectorAll(".tab").forEach(t => t.classList.remove("active"));
        el.classList.add("active");
        currentGame = key;
        render();
      });
      document.getElementById(game.group === "fc" ? "tabs-fc" : "tabs-tc").appendChild(el);
    });
  }

  // 快乐8 选号个数下拉框
  function buildPicksSelect() {
    const vc = GAMES.kl8.variableCount;
    const sel = document.getElementById("picks");
    const names = ["一","二","三","四","五","六","七","八","九","十"];
    for (let i = vc.min; i <= vc.max; i++) {
      const opt = document.createElement("option");
      opt.value = i;
      opt.textContent = `选${names[i - 1]}(${i}个)`;
      if (i === vc.def) opt.selected = true;
      sel.appendChild(opt);
    }
  }

  document.getElementById("generate").addEventListener("click", () => {
    const n = parseInt(document.getElementById("count").value, 10);
    const picks = currentPicks();
    results[currentGame] = Array.from({ length: n }, () => generateTicket(currentGame, picks));
    render();
  });

  document.getElementById("copy").addEventListener("click", async () => {
    const tickets = results[currentGame];
    if (!tickets.length) return showToast("请先生成号码");
    const game = GAMES[currentGame];
    const text = `【${game.name}】\n` + tickets.map((t, i) => {
      const parts = t.map((nums, zi) => {
        const zone = game.zones[zi];
        const body = nums.map(n => fmt(n, zone)).join(" ");
        return game.zones.length === 1 && zone.label === "号码"
          ? body
          : `${zone.label}: ${body}`;
      });
      return `第${i + 1}注  ${parts.join("  ")}`;
    }).join("\n");
    try {
      await navigator.clipboard.writeText(text);
      showToast("已复制到剪贴板");
    } catch {
      showToast("复制失败,请手动选择文本");
    }
  });

  buildTabs();
  buildPicksSelect();
  render();
</script>
</body>
</html>
```

**各玩法的实现方式**

| 玩法 | 生成逻辑 |
|---|---|
| 双色球 / 大乐透 | 各区不重复、升序 |
| 福彩3D / 排列3 / 排列5 | 每位 0-9 独立随机,可重复,不排序,显示单个数字 |
| 七乐彩 | 先抽 7 个基本号,特别号再从剩余的 23 个号码里抽,保证不重复 |
| 快乐8 | 1-80 不重复升序,选中该标签页时会出现"选号个数"下拉框,可选选一到选十 |
| 七星彩 | 前 6 位 0-9 可重复,最后 1 位 0-14 |

**结构上的改动**

- 所有玩法都由 `GAMES` 配置对象描述,每个玩法拆成若干"号码区",生成、渲染、复制都是同一套通用代码。以后要加新玩法,只需要补一项配置。
- 顶部标签页按福彩、体彩分成两组,每个彩种各自保留已生成的结果,切换时不会丢。
- 复制文本示例:

```
【七乐彩】
第1注  基本号: 02 07 13 18 22 26 29  特别号: 11

【排列3】
第1注  4 0 7
```

七星彩的后区规则、快乐8的玩法等如果官方后续有调整,只需要改对应的配置项即可。随机选号不会提高中奖概率,仅供娱乐。
